def shapes(g):
    from collections import Counter
    c=Counter(x for r in g for x in r)
    bg=c.most_common(1)[0][0]
    seen=set(); out=[]
    for i,row in enumerate(g):
        for j,v in enumerate(row):
            if v!=bg and (i,j) not in seen:
                cols=[k for k in range(len(row)) if row[k]==v]
                # find bbox by flood of border color value v
                stack=[(i,j)]; comp=set()
                while stack:
                    a,b=stack.pop()
                    if (a,b) in comp or g[a][b]!=v: continue
                    comp.add((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<len(g) and 0<=nb<len(g[0]): stack.append((na,nb))
                seen|=comp
                rs=[a for a,_ in comp]; cs=[b for _,b in comp]
                out.append((min(rs),max(rs),min(cs),max(cs),v))
    return bg,out

def transform(g):
    bg,ss=shapes(g)
    g=[r[:] for r in g]
    for r0,r1,c0,c1,v in ss:
        for i in range(r0+1,r1):
            for j in range(c0+1,c1):
                g[i][j]= 7 if ((r1-r0-1)*(c1-c0-1))%2 else 2
    return g

